WITH recent_web_events AS (SELECT * FROM web_events WHERE page IN ('/product', '/cart') AND page IN ('/product', '/home', '/checkout')), WebEventsStats AS (SELECT CASE WHEN YEAR(event_time) < 2024 THEN 'before_2024' WHEN YEAR(event_time) = 2024 THEN '2024' ELSE 'after_2024' END event_cohort, CASE WHEN event_type IN ('add_to_cart', 'click') THEN 'priority' ELSE 'other' END event_type_group, SUM(duration_sec) total_duration_sec, ROUND((100 * SUM(CASE WHEN page = '/search' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_search FROM recent_web_events GROUP BY CASE WHEN YEAR(event_time) < 2024 THEN 'before_2024' WHEN YEAR(event_time) = 2024 THEN '2024' ELSE 'after_2024' END, CASE WHEN event_type IN ('add_to_cart', 'click') THEN 'priority' ELSE 'other' END) SELECT * FROM WebEventsStats WHERE pct_search >= 44 ORDER BY 3 DESC, event_cohort, event_type_group LIMIT 20;
